/**
 * Returns a Course with content fields overlaid from the given locale's translations.
 * Falls back to the original English content for any untranslated field.
 */
export function getLocalizedCourse(course: Course, locale: string): Course {
  if (locale === 'en' || !courseTranslations[locale]) return course;
  const overrides = courseTranslations[locale]?.[course.slug] ?? {};
  return { ...course, ...overrides };
}

/**
 * Returns all courses with content fields overlaid from the given locale's translations.
 */
export function localizeAllCourses(courses: Course[], locale: string): Course[] {
  if (locale === 'en') return courses;
  return courses.map((c) => getLocalizedCourse(c, locale));
}
